import{_ as o,o as t,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Vendors — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Vendors — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/vendors"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Vendors — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/vendors"}]]},"headers":[],"relativePath":"deployment/vendors.md","filePath":"deployment/vendors.md","lastUpdated":1787321193000}'),r={name:"deployment/vendors.md"};function s(i,e,d,l,c,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="vendors-—-production-guide" tabindex="-1">Vendors — Production Guide <a class="header-anchor" href="#vendors-—-production-guide" aria-label="Permalink to &quot;Vendors — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>vendors</code></li><li>Category: <code>purchasing</code> (<strong>Purchasing</strong>), <code>category_sort_order = 40</code></li><li><strong>Free Marketplace opt-in</strong> module (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 10</code></li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> by default; enable Vendors from Marketplace</li><li>Existing workspaces that already have Vendors keep their subscription</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong> only)</li><li>Operators enable Vendors from Marketplace (free / non-billable install activates immediately)</li><li>Tenant permissions include <code>vendors.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>No stage or status seeder (unlike Leads) — Vendors is a flat directory record with a simple <code>active</code>/<code>inactive</code> flag.</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Vendors permissions for <strong>existing</strong> workspaces must ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>vendor_created</code>, <code>vendor_updated</code>, <code>vendor_deleted</code>, <code>vendor_assigned</code>, <code>vendor_note_added</code>, <code>vendor_restored</code></li><li>Notifications: assignment (mail + database) via <code>VendorAssignedNotification</code></li><li>Tenant mail settings with Central SMTP fallback</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate vendor tables (<code>vendors</code>, <code>vendor_notes</code>, <code>vendor_activities</code>)</li><li>Register the <code>vendors</code> catalog module (migration, not seeder) as free opt-in under the new <code>purchasing</code> category</li><li>Confirm <code>module:vendors</code> + <code>vendors.*</code> permissions on target roles</li><li>Deploy frontend (Vendors nav item under new <strong>Purchasing</strong> group, list/form/detail)</li><li>Smoke: create a <strong>new</strong> workspace → enable Vendors from Marketplace → create/edit/assign/note a vendor → soft delete/restore</li></ol><h2 id="phase-4-roadmap-context" tabindex="-1">Phase 4 roadmap context <a class="header-anchor" href="#phase-4-roadmap-context" aria-label="Permalink to &quot;Phase 4 roadmap context&quot;">​</a></h2><p>Vendors is Milestone 1 of <strong>Phase 4 Purchasing</strong>. Purchase Orders (Milestone 2) hard-depends on Vendors; Expenses (Milestone 3, final) has a soft dependency on both Vendors and Purchase Orders. Phase 4 Purchasing is now complete. See <a href="/architecture/module-dependencies">module-dependencies.md</a> and <a href="/getting-started/product-roadmap">product-roadmap.md</a>.</p>',15)])])}const u=o(r,[["render",s]]);export{g as __pageData,u as default};
